// One input format for every source: landing, Gmail, Fireflies, Gaius Meet, and later the CRM.
// brief = { source, segment?, role?, email?, client?, text?, hasText }
const SEGMENTS = ['law-firm', 'in-house', 'public-sector'];
const ROLES = ['champion', 'board'];
const input = $input.first().json;
const raw = input.body ?? input;
const pick = (v, allowed) => (allowed.includes(v) ? v : null);

const email = String(raw.email || '').trim().slice(0, 200);
const text = String(raw.text || raw.transcript || raw.notes || '').trim().slice(0, 60000);

// Without text we only guess the segment from the email domain. A weak signal: the AI overrides it when there is text.
const domain = email.split('@')[1]?.toLowerCase() || '';
const segmentFromDomain = /(^|\.)gov\.|\.gov$|gmina|powiat|urzad|um\.|ug\.|starostwo|(^|\.)bip\./.test(domain)
  ? 'public-sector'
  : /kancelaria|legal|law|lex|adwokat|radca|prawn/.test(domain) ? 'law-firm' : null;

return [{ json: {
  source: String(raw.source || 'landing'),
  segment: pick(raw.segment, SEGMENTS) ?? segmentFromDomain,
  role: pick(raw.role, ROLES),
  email: email || null,
  client: raw.client ? String(raw.client).slice(0, 200) : null,
  text,
  hasText: text.length > 0,
  receivedAt: new Date().toISOString(),
} }];

// The decisions n8n makes: which tiles the offer is generated from.
// Defaults (we know nothing): role = board, segment = in-house, product = Vault,
// pains = the two concerns every legal buyer has (confidentiality, hallucinated citations).
const brief = $('Brief').first().json;
let ai = {};
try { ai = $('Analyze lead (AI)').first().json || {}; } catch (e) { ai = {}; }
if (ai.error) ai = {};

const SEGMENT_OK = ['law-firm', 'in-house', 'public-sector'];
const segment = [brief.segment, ai.segment].find((s) => SEGMENT_OK.includes(s)) ?? 'in-house';
const role = [brief.role, ai.role].find((r) => r === 'champion' || r === 'board') ?? 'board';
const product = (typeof ai.product === 'string' && ai.product.startsWith('product:')) ? ai.product : 'product:vault';
const pains = Array.isArray(ai.pains) && ai.pains.length
  ? ai.pains.slice(0, 5)
  : ['pain:confidentiality', 'pain:hallucinated-citations'];

const WHO = { 'law-firm': 'Law firm', 'in-house': 'In-house legal', 'public-sector': 'Public administration' }[segment];
const client = brief.client || ai.client || null;
return [{ json: {
  known: brief.hasText && !!ai.summary,
  segment, role, client, product, pains,
  person: ai.person || null,
  concerns: Array.isArray(ai.concerns) ? ai.concerns.slice(0, 3) : [],
  summary: ai.summary || null,
  who: [ai.person, client, WHO].filter(Boolean).join(' · '),
  tiles: [`role:${role}`, `segment:${segment}`, product, ...pains],
  offerClient: client || WHO,
} }];

const plan = $('Offer plan').first().json;
const offer = $('Generate offer').first().json;
const started = new Date($('Brief').first().json.receivedAt).getTime();
return [{ json: {
  offerId: offer.id,
  offerName: offer.name,
  known: plan.known,
  segment: plan.segment,
  role: plan.role,
  who: plan.who,
  client: plan.client,
  concerns: plan.concerns,
  tiles: plan.tiles,
  coverage: offer.coverage ?? null,
  summary: plan.summary,
  pdfPath: `/webhook/offer-pdf?id=${encodeURIComponent(offer.id)}`,
  ms: Date.now() - started,
} }];

// For the hackathon the CRM write and the #sales alert are mocked. Connect the real nodes here.
const r = $input.first().json;
return [{ json: {
  crm: { stage: 'Offer', offerId: r.offerId, who: r.who, nextActivity: 'follow-up call in 2 days' },
  discord: { channel: '#sales', text: `New offer ready for ${r.who}. Offer Studio: ${r.offerId}` },
} }];
